
var multi_steps_forms = document.getElementsByClassName("multi-steps-form");

function change_step(origen_step, target_step, faded) {
    let delay = faded ? 150 : 0;

    // Hide all steps
    document.querySelectorAll(".step").forEach(step => {
        step.classList.remove("show");
        step.style.display = "none"; // Add this line to hide the step
    });

    origen_step.classList.remove("active");

    target_step.style.display = "block"; // Show the target_step

    setTimeout(() => {
        target_step.classList.add("show");
        target_step.classList.add("active");

        // Scroll to the top of the step
        target_step.scrollTop = 0;

        // Apply custom styles to target_step (adjust as needed)
        target_step.style.position = "relative";
        target_step.style.top = "0";
        target_step.style.left = "0";
        target_step.style.transform = "translate(0, 0)";
        target_step.style.transition = "transform 0.3s ease"; // Add smooth transition if desired
    }, delay);
}

// Function to check if the fields in a step are valid and focus on them one by one
function isStepValid(step, index = 0) {
    const fields = step.querySelectorAll('input[required], select[required], textarea[required]');
    if (index < fields.length) {
        const field = fields[index];
        if (!field.checkValidity()) {
            // Field is not valid, return false
            return false;
        } else {
            // Field is valid, focus on it
            field.focus();
            // Use a timeout to focus on the next field
            setTimeout(() => {
                isStepValid(step, index + 1);
            }, 100); // Adjust the delay as needed
        }
    }
    // All required fields are valid
    return true;
}

// Modify the click event listener for step links
Array.prototype.forEach.call(multi_steps_forms, (function (form) {
    form.querySelectorAll(".step").forEach(step => {
        var faded = form.classList.contains("faded");
        step.querySelectorAll(".step-link").forEach(
            step_link => {
                var step_target = step_link.getAttribute("data-bs-target");
                step_link.addEventListener("click", () => {
                    if (isStepValid(step)) {
                        change_step(step, form.querySelector(step_target), faded);
                    } else {
                        var responseElement = document.getElementById('response');
                        var errMessage = "Please Fill In All Required Fields(*) Before Proceeding.";
                        // Set the text content and add the 'alert-danger' class
                        responseElement.textContent = errMessage;
                        responseElement.classList.add('alert-primary');

                        // Display an error message or take other action
                        //console.log("Please fill in all required fields before proceeding.");
                    }
                });
            }
        );
    });
}));



class MultiStepForm {
    constructor(form_selector) {
        this.form = document.querySelector(form_selector);
        this.faded = this.form.classList.contains("faded");
    }

    show(step_selector) {
        const target_step = this.form.querySelector(step_selector);
        const origen_step = this.form.querySelector(".step.active");
        change_step(origen_step, target_step, this.faded);
    }
}
